import{_ as a,o as t,c as s,ae as n}from"./chunks/framework.1Lna8NcP.js";const h=JSON.parse('{"title":"ADR-002: Taxes Page","description":"","frontmatter":{},"headers":[],"relativePath":"adr/002-taxes-page.md","filePath":"adr/002-taxes-page.md"}'),i={name:"adr/002-taxes-page.md"};function r(o,e,d,c,l,u){return t(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="adr-002-taxes-page" tabindex="-1">ADR-002: Taxes Page <a class="header-anchor" href="#adr-002-taxes-page" aria-label="Permalink to &quot;ADR-002: Taxes Page&quot;">​</a></h1><p><strong>Date:</strong> 2026-04-05 <strong>Status:</strong> Accepted</p><hr><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Users may have multiple income types (W-2, 1099/self-employment, rental, crypto) and varying business entity structures. They need to understand their tax position, reduce liability legally, and get jurisdiction-aware recommendations on business structure. This is not covered in ADR-001.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Add a dedicated <strong>Taxes</strong> page with three responsibilities:</p><ol><li><p><strong>Running tax estimate</strong> — current-year federal + state liability broken down by income type, updated as transactions are imported. Prior years in a collapsed history section.</p></li><li><p><strong>Tax-loss harvesting</strong> — surfaces unrealized losses with estimated savings and wash-sale warnings. Shown as a proactive Insights card + full detail section on the Taxes page.</p></li><li><p><strong>Entity structure recommendations</strong> — powered by user profile (income, location, business activity). Shows recommended entity, plain-English rationale, estimated annual tax savings vs current structure, and a setup checklist.</p></li></ol><h2 id="jurisdiction-awareness" tabindex="-1">Jurisdiction Awareness <a class="header-anchor" href="#jurisdiction-awareness" aria-label="Permalink to &quot;Jurisdiction Awareness&quot;">​</a></h2><p>All tax guidance uses <code>country</code> + <code>state</code> from the user profile in Settings. State-specific rules (no-income-tax states, community property, etc.) are factored in where applicable.</p><h2 id="ai-dependency" tabindex="-1">AI Dependency <a class="header-anchor" href="#ai-dependency" aria-label="Permalink to &quot;AI Dependency&quot;">​</a></h2><p>Entity structure recommendations and complex tax strategy interpretation require the Claude API (opt-in, key in <code>.env</code>). Running estimates and loss harvesting are rule-based and work without an API key.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>New <code>Taxes</code> router in backend</li><li>Tax estimate logic must handle: short-term vs long-term capital gains, self-employment tax (15.3%), qualified dividends, rental income deductions</li><li>User profile fields added to <code>settings</code> table (see spec for full list)</li><li><code>.env</code> keeps API keys out of the DB and git</li></ul>',14)])])}const m=a(i,[["render",r]]);export{h as __pageData,m as default};
